// 3D model of the thyroid and central neck from Z-Anatomy meshes (CC BY-SA
// 4.0, based on BodyParts3D), plus paths drawn for this app where Z-Anatomy
// has no model (recurrent and superior laryngeal nerves, superior thyroid
// artery, middle and inferior thyroid veins). Geometry lives in
// data/thyroid-meshes.js, generated by tools/export_zanatomy.py.
// Coordinates are centimetres centred on the thyroid: +y = superior,
// +z = anterior, and the patient's left side is +x.

window.ANATOMY = window.ANATOMY || { regions: {} };
window.ANATOMY.models = window.ANATOMY.models || {};

window.ANATOMY.models.thyroid = {
  // Default view: from the front and slightly to the right, as at thyroidectomy.
  camera: { target: [0, 0.2, 0.6], radius: 24, theta: -0.35, phi: 1.6 },

  // [theta, phi] for the view buttons. "Lateral" shows the right side (-x).
  views: {
    lateral: [-Math.PI / 2, Math.PI / 2],
    inferior: [-0.2, 2.6],
    anterior: [0, 1.6]
  },

  // Starting axial level (0 = bottom of the model, 1 = top): through the lobes.
  sectionLevel: 0.6,

  look: {
    hyoid: { kind: "bone" },
    larynx: { kind: "cartilage" },
    trachea: { kind: "cartilage", color: 0xd9cbb2 },
    sternum: { kind: "bone" },
    clavicles: { kind: "bone" },
    vertebrae: { kind: "bone", opacity: 0.6 },
    thyroid: { kind: "gland", color: 0xa8423a },
    parathyroid_superior: { kind: "gland", color: 0xc79a4a },
    parathyroid_inferior: { kind: "gland", color: 0xc79a4a },
    thymus: { kind: "gland", color: 0xe0c08e, opacity: 0.7 },
    sternohyoid: { kind: "muscle", color: 0xa4423f },
    sternothyroid: { kind: "muscle", color: 0x9c3d3c },
    thyrohyoid: { kind: "muscle", color: 0x9a3c3c },
    omohyoid: { kind: "muscle", color: 0xa13f3d },
    scm: { kind: "muscle", color: 0xa4423f },
    cricothyroid: { kind: "muscle", color: 0x943a3b },
    constrictor: { kind: "muscle", color: 0x8f3739 },
    oesophagus: { kind: "muscle", color: 0xb8655a },
    platysma: { kind: "muscle", color: 0xc2685a, opacity: 0.35 },
    cca: { kind: "artery" },
    ita: { kind: "artery" },
    subclavian_arteries: { kind: "artery" },
    superior_thyroid_artery: { kind: "artery" },
    ijv: { kind: "vein" },
    brachiocephalic_veins: { kind: "vein" },
    ajv: { kind: "vein" },
    superior_thyroid_vein: { kind: "vein" },
    middle_thyroid_vein: { kind: "vein" },
    inferior_thyroid_veins: { kind: "vein" },
    vagus: { kind: "nerve" },
    rln_right: { kind: "nerve" },
    rln_left: { kind: "nerve" },
    sln: { kind: "nerve" },
    ebsln: { kind: "nerve" },
    nodes_vi: { kind: "node", color: 0xe06a9a },
    nodes_lateral: { kind: "node" }
  },

  build(THREE, h) {
    return h.fromMeshes("thyroid", this.look);
  }
};
